-- 2026-10-w4 G2 動画レビュー: A79 のヒント・A80 / C79 の情景を修正
-- A79
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "英語のなぞなぞ、いくぞ!", "hint": "中のTは文字ではないぞ!", "question": "Tで始まり、Tで終わり、中にもTが入っているものは? 台所にあるぞ。", "answer": "teapot(ティーポット。中にtea=ティーが入っている)", "explanation": "teapot(ティーポット)はTで始まりTで終わる。そして中に入っているのはtea(ティー=お茶)。文字のTと飲み物のティーを掛けたなぞなぞだ。", "coach_comment": "お茶でも飲んで一息だ!", "tags": ["なぞなぞ", "朝の一問", "英語なぞ"], "summary": "Tで始まりTで終わり、中にTが入っているものを問う英語圏の定番なぞ。答えはteapot。つづりのTと、中に入っているtea(お茶)を掛ける。", "illustration_scene": "朝日が差し込む台所のテーブルに、白い無地のカードが1枚立ててある。カードには大きく「T … T」と書いてある。テーブルの上はカードと、緑の葉の小さな観葉植物の鉢だけ。カードの右上に大きな「?」。人物と、「T … T」「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'morning-075';
-- A80
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "朝の指体操、いくぞ!", "hint": "指ごとに重さを変えてみろ!", "question": "片手の指は5本。ふつうに数えれば5までだ。でも数え方を工夫すると、片手だけで31まで数えられる。どうやる?", "answer": "指の立て・曲げを2進数の各けたに使う", "explanation": "親指を1、人差し指を2、中指を4、薬指を8、小指を16と決め、立てた指の値を足す。全部立てれば31。両手なら1023まで数えられるぞ。", "coach_comment": "指の使い方が天才的だ!", "tags": ["なぞなぞ", "朝の一問", "参加型"], "summary": "片手の指だけで31まで数える方法を問う定番。指に1・2・4・8・16を割り当て、立てた指の値を足す2進数の数え方。視聴者がその場で試せる参加型。", "illustration_scene": "自分の目で手元を見下ろした一人称視点の構図。画面の下から自分の片手が伸び、5本の指を開いた手のひらを上に向けて、真上から見下ろしている。手の下は朝日が差し込む窓辺の木の机。手の上に大きな「?」。手以外の人物は描かない。「?」以外の文字や数字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'morning-076';
-- C79
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "寝てる間に300km!?", "hint": "車が動いたとは限らないぞ!", "question": "男は車の中でぐっすり眠った。エンジンは一度もかけていない。なのに目を覚ますと、車ごと300kmも離れた町にいた。なぜ?", "answer": "車ごと運ばれていた(キャリアカー・フェリーなど)", "explanation": "車を何台も載せて運ぶトラック(キャリアカー)やフェリーに、車ごと載っていた。エンジンは止めたままでも、寝ている間に300km先へ。動いたのは車ではない。", "coach_comment": "動いたのは車じゃなかったな!", "tags": ["水平思考", "夜の一問", "状況パズル"], "summary": "エンジンをかけずに眠っていた男が、目を覚ますと車ごと300km先の町にいた理由を問う水平思考。車ごと何かに載せられて運ばれていた(キャリアカー・フェリーなど。別解を取り込む)。", "illustration_scene": "夜、車の運転席から見た暗い車内。フロントガラスの外は一面の暗い紺色だけで、景色も明かりも見えない。車内はメーターのほのかな明かりで、ハンドルとダッシュボードの形が見分けられる。ハンドルの上に大きな「?」。人物・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'night-073';
